import {
  Box,
  Stack,
  Typography,
  ToggleButton,
  ToggleButtonGroup,
} from "@mui/material";

import {
  ModelTrainingRounded,
  RefreshRounded,
} from "@mui/icons-material";

import ForecastContextBar from "../../../components/layout/ForecastContextBar";

import {
  useForecastContext,
} from "../../../contexts/ForecastContext";

import ModelPerformanceKPIs from "../components/ModelPerformanceKPIs";

import OotPerformanceChart from "../components/OotPerformanceChart";

import ModelAccuracyMatrix from "../components/ModelAccuracyMatrix";

import {
  PerformanceHorizon,
  PerformanceTarget,
} from "../types/model-performance.types";


const ModelPerformancePage = () => {
  const {
    horizon,
    metric,
    entityId,
  } = useForecastContext();


  /*
   * ==================================================
   * PERFORMANCE HORIZON
   * ==================================================
   *
   * Forecast context:
   *
   * daily   -> tactical
   * monthly -> strategic
   *
   * We keep the frontend terminology here because
   * that is what the rest of the dashboard uses.
   */

  const performanceHorizon:
    PerformanceHorizon =
      horizon === "monthly"
        ? "monthly"
        : "daily";


  /*
   * ==================================================
   * PERFORMANCE TARGET
   * ==================================================
   *
   * Forecast metric:
   *
   * burn      -> Input
   * supply    -> Replenishment
   * stockpile -> Stockpile
   */

  const target:
    PerformanceTarget =
      metric === "supply"
        ? "Replenishment"
        : metric === "stockpile"
          ? "Stockpile"
          : "Input";


  /*
   * ==================================================
   * OOT CHART METRIC
   * ==================================================
   *
   * OotPerformanceChart expects:
   *
   * Input
   * Replenishment
   * Stockpile
   */

  const ootMetric:
    | "Input"
    | "Replenishment"
    | "Stockpile" =
      target;


  return (
    <Box
      sx={{
        width: "100%",

        minHeight: "100%",

        bgcolor: "#F5F7FA",

        px: {
          xs: 2,
          sm: 3,
          md: 4,
          lg: 5,
        },

        py: {
          xs: 2,
          md: 4,
        },

        boxSizing: "border-box",
      }}
    >

      <Box
        sx={{
          width: "100%",

          maxWidth: 1600,

          mx: "auto",

          minWidth: 0,
        }}
      >

        {/* ==================================================
            PAGE HEADER
        ================================================== */}

        <Stack
          direction={{
            xs: "column",
            md: "row",
          }}
          justifyContent="space-between"
          alignItems={{
            xs: "flex-start",
            md: "center",
          }}
          spacing={2}
          mb={4}
        >

          <Box
            sx={{
              minWidth: 0,
            }}
          >

            <Stack
              direction="row"
              spacing={1.5}
              alignItems="center"
            >

              <Box
                sx={{
                  width: 52,
                  height: 52,

                  borderRadius: 3,

                  bgcolor:
                    "#EEF4FF",

                  color:
                    "#1264FF",

                  display:
                    "flex",

                  alignItems:
                    "center",

                  justifyContent:
                    "center",

                  flexShrink: 0,
                }}
              >

                <ModelTrainingRounded
                  sx={{
                    fontSize: 28,
                  }}
                />

              </Box>


              <Box
                sx={{
                  minWidth: 0,
                }}
              >

                <Typography
                  variant="h4"
                  fontWeight={800}
                  color="#172B4D"
                >
                  Model Performance
                </Typography>


                <Typography
                  variant="body1"
                  color="text.secondary"
                  mt={0.5}
                >
                  Understand how accurately
                  the forecasting models are
                  performing.
                </Typography>

              </Box>

            </Stack>

          </Box>


          {/* LIVE BACKEND INDICATOR */}

          <Stack
            direction="row"
            spacing={1}
            alignItems="center"
            sx={{
              color:
                "#68758A",
            }}
          >

            <RefreshRounded
              sx={{
                fontSize: 20,
              }}
            />


            <Typography
              variant="body2"
              fontWeight={600}
            >
              Live backend metrics
            </Typography>

          </Stack>

        </Stack>


        {/* ==================================================
            SHARED FORECAST CONTEXT
        ================================================== */}

        <Box
          mb={4}
          minWidth={0}
        >
          <ForecastContextBar />
        </Box>


        {/* ==================================================
            PERFORMANCE CONTEXT
        ================================================== */}

        <Box
          sx={{
            bgcolor:
              "#FFFFFF",

            border:
              "1px solid #E2E7EF",

            borderRadius: 4,

            px: {
              xs: 2.5,
              md: 4,
            },

            py: 2,

            mb: 3,

            boxShadow:
              "0 8px 24px rgba(23,43,77,0.04)",

            minWidth: 0,
          }}
        >

          <Stack
            direction={{
              xs: "column",
              sm: "row",
            }}
            justifyContent="space-between"
            alignItems={{
              xs:
                "flex-start",
              sm:
                "center",
            }}
            spacing={2}
          >

            <Box
              sx={{
                minWidth: 0,
              }}
            >

              <Typography
                variant="subtitle1"
                fontWeight={800}
                color="#172B4D"
              >
                Evaluation View
              </Typography>


              <Typography
                variant="body2"
                color="text.secondary"
              >
                Review performance for the
                selected forecast context.
              </Typography>

            </Box>


            <ToggleButtonGroup
              exclusive
              value={
                performanceHorizon
              }
              size="small"
              disabled
              sx={{
                flexShrink: 0,

                "& .MuiToggleButton-root":
                  {
                    px: 2.5,

                    fontWeight: 700,

                    textTransform:
                      "none",
                  },
              }}
            >

              <ToggleButton
                value="daily"
              >
                Tactical Daily
              </ToggleButton>


              <ToggleButton
                value="monthly"
              >
                Strategic Monthly
              </ToggleButton>

            </ToggleButtonGroup>

          </Stack>

        </Box>


        {/* ==================================================
            PERFORMANCE DASHBOARD
        ================================================== */}

        <Stack
          spacing={3}
          mb={3}
          minWidth={0}
        >

          {/* ==================================================
              KPI CARDS
          ================================================== */}

          <ModelPerformanceKPIs
            horizon={
              performanceHorizon
            }
            entityId={
              entityId
            }
          />


          {/* ==================================================
              OUT-OF-TIME PERFORMANCE
          ================================================== */}

          <OotPerformanceChart
            horizon={
              performanceHorizon
            }

            entityId={
              entityId
            }

            metric={
              ootMetric
            }
          />


          {/* ==================================================
              ACCURACY MATRIX
          ================================================== */}

          <ModelAccuracyMatrix
            horizon={
              performanceHorizon
            }
            entityId={
              entityId
            }
          />

        </Stack>

      </Box>

    </Box>
  );
};


export default ModelPerformancePage;
